#!/usr/bin/env node
/*
 * vm.js -- MIPS32 (little-endian, o32) user-mode interpreter with Linux-style
 * system call emulation, sufficient to boot doomgeneric_mips and let it render
 * and save frames.
 *
 * Usage:  node vm.js [elf-file]
 *
 * The guest writes each rendered frame with a BMP file (see doomgeneric_img.c).
 * Every such file is written through to the real filesystem and additionally
 * archived as a numbered copy (frame0000.bmp, frame0001.bmp, ...) so that the
 * frames are kept one at a time as they are rendered.
 */
'use strict';

const fs = require('fs');
const pathmod = require('path');

/* ------------------------------------------------------------------ config */

const ELF_PATH = process.argv[2] ||
      process.env.DOOM_ELF ||
      (fs.existsSync('/app/doomgeneric_mips') ? '/app/doomgeneric_mips'
                                             : './doomgeneric_mips');
const ELF_DIR = pathmod.dirname(pathmod.resolve(ELF_PATH));

/* how many frames to save before stopping (0 = run forever) */
const MAX_FRAMES = process.env.DOOM_MAX_FRAMES !== undefined
      ? parseInt(process.env.DOOM_MAX_FRAMES, 10) : 20;
/* directories that receive the numbered frame copies */
const FRAME_DIRS = [process.cwd(), '/tmp'];

const STACK_SIZE = 8 * 1024 * 1024;

/* ------------------------------------------------------------- elf loading */

function loadElf(file) {
  const b = fs.readFileSync(file);
  if (b[0] !== 0x7f || b[1] !== 0x45 || b[2] !== 0x4c || b[3] !== 0x46)
    throw new Error('not an ELF file: ' + file);
  if (b[4] !== 1) throw new Error('only ELF32 supported');
  if (b[5] !== 1) throw new Error('only little-endian supported');
  const e_machine = b.readUInt16LE(18);
  if (e_machine !== 8) throw new Error('not a MIPS ELF (e_machine=' + e_machine + ')');
  const entry = b.readUInt32LE(24) >>> 0;
  const phoff = b.readUInt32LE(28);
  const phentsize = b.readUInt16LE(42);
  const phnum = b.readUInt16LE(44);

  const segs = [];
  let top = 0;
  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    const p_type = b.readUInt32LE(o);
    if (p_type !== 1 /* PT_LOAD */) continue;
    const p_offset = b.readUInt32LE(o + 4);
    const p_vaddr = b.readUInt32LE(o + 8) >>> 0;
    const p_filesz = b.readUInt32LE(o + 16);
    const p_memsz = b.readUInt32LE(o + 20);
    segs.push({ p_offset, p_vaddr, p_filesz, p_memsz });
    if (p_vaddr + p_memsz > top) top = p_vaddr + p_memsz;
  }
  return { buf: b, entry, segs, top };
}

const elf = loadElf(ELF_PATH);

/* memory is a flat buffer indexed directly by guest address */
const MEM_SIZE = ((elf.top + STACK_SIZE + 0xffff) & ~0xffff) >>> 0;
const membuf = new ArrayBuffer(MEM_SIZE);
const U8 = new Uint8Array(membuf);
const I8 = new Int8Array(membuf);
const U16 = new Uint16Array(membuf);
const I16 = new Int16Array(membuf);
const I32 = new Int32Array(membuf);
const U32 = new Uint32Array(membuf);

for (const s of elf.segs) {
  U8.set(elf.buf.subarray(s.p_offset, s.p_offset + s.p_filesz), s.p_vaddr);
  /* the rest of p_memsz (.bss) is already zero */
}

/* --------------------------------------------------------------- cpu state */

const R = new Int32Array(32);      /* general purpose registers */
const FGR = new Uint32Array(32);   /* fpu registers, raw 32 bit words (FR=0) */
let HI = 0, LO = 0;
let FCC = 0;                       /* fpu condition codes, 8 bits */
let FCSR = 0;
let pc = elf.entry >>> 0;
let npc = (pc + 4) >>> 0;

/* scratch used for raw <-> float conversions */
const cvtBuf = new ArrayBuffer(8);
const cvtU32 = new Uint32Array(cvtBuf);
const cvtF32 = new Float32Array(cvtBuf);
const cvtF64 = new Float64Array(cvtBuf);

function getS(n) { cvtU32[0] = FGR[n]; return cvtF32[0]; }
function setS(n, v) { cvtF32[0] = v; FGR[n] = cvtU32[0]; }
function getD(n) { cvtU32[0] = FGR[n & ~1]; cvtU32[1] = FGR[(n & ~1) + 1]; return cvtF64[0]; }
function setD(n, v) { cvtF64[0] = v; FGR[n & ~1] = cvtU32[0]; FGR[(n & ~1) + 1] = cvtU32[1]; }

const STACK_TOP = (MEM_SIZE - 256) & ~0xf;
R[29] = STACK_TOP | 0;                 /* $sp */
R[28] = 0;                             /* $gp (unused, static model) */
R[31] = 0;                             /* $ra */
R[4] = 0; R[5] = 0;                    /* argc / argv for __start */

/* ----------------------------------------------------------- memory access */

function fault(addr, what) {
  throw new Error('memory fault: ' + what + ' at 0x' + (addr >>> 0).toString(16) +
                  ' (pc=0x' + (pc >>> 0).toString(16) + ')');
}

function rd32(a) {
  if ((a >>> 0) + 4 > MEM_SIZE) fault(a, 'read32');
  if (a & 3) {
    return (U8[a] | (U8[a + 1] << 8) | (U8[a + 2] << 16) | (U8[a + 3] << 24)) | 0;
  }
  return I32[a >>> 2];
}
function wr32(a, v) {
  if ((a >>> 0) + 4 > MEM_SIZE) fault(a, 'write32');
  if (a & 3) {
    U8[a] = v; U8[a + 1] = v >>> 8; U8[a + 2] = v >>> 16; U8[a + 3] = v >>> 24;
  } else I32[a >>> 2] = v;
}

/* -------------------------------------------------------------- 64 bit mul */

function umulHi(a, b) {           /* a, b: uint32 -> high 32 bits of product */
  const a0 = a & 0xffff, a1 = a >>> 16, b0 = b & 0xffff, b1 = b >>> 16;
  const p0 = a0 * b0;
  const p1 = a1 * b0 + (p0 >>> 16);
  const p2 = a0 * b1 + (p1 & 0xffff);
  return (a1 * b1 + (p1 >>> 16) + (p2 >>> 16)) >>> 0;
}

/* ------------------------------------------------------------ file helpers */

const O_RDONLY = 0, O_WRONLY = 1, O_RDWR = 2;
const O_CREAT = 64, O_EXCL = 128, O_TRUNC = 512, O_APPEND = 1024;
const EBADF = 9, ENOENT = 2, EINVAL = 22, EIO = 5, ENOSYS = 38;

const files = new Map();   /* guest fd -> {pos, path, writable} */
let frameCount = 0;
let exiting = false;

function resolveGuestPath(p) {
  if (pathmod.isAbsolute(p)) return p;
  const inCwd = pathmod.resolve(process.cwd(), p);
  if (fs.existsSync(inCwd)) return inCwd;
  const nearElf = pathmod.resolve(ELF_DIR, p);
  if (fs.existsSync(nearElf)) return nearElf;
  return inCwd;
}

function cstr(addr) {
  let s = '';
  let a = addr >>> 0;
  for (;;) {
    if (a >= MEM_SIZE) fault(a, 'cstr');
    const c = U8[a++];
    if (c === 0) break;
    s += String.fromCharCode(c);
  }
  return s;
}

function flagsToNode(flags) {
  const acc = flags & 3;
  let f;
  if (acc === O_RDONLY) f = fs.constants.O_RDONLY;
  else if (acc === O_WRONLY) f = fs.constants.O_WRONLY;
  else f = fs.constants.O_RDWR;
  if (flags & O_CREAT) f |= fs.constants.O_CREAT;
  if (flags & O_EXCL) f |= fs.constants.O_EXCL;
  if (flags & O_TRUNC) f |= fs.constants.O_TRUNC;
  if (flags & O_APPEND) f |= fs.constants.O_APPEND;
  return f;
}

function isFramePath(p) {
  return /frame[^/]*\.bmp$/i.test(p);
}

function archiveFrame(realPath) {
  let data;
  try { data = fs.readFileSync(realPath); } catch (e) { return; }
  const name = 'frame' + String(frameCount).padStart(4, '0') + '.bmp';
  for (const d of FRAME_DIRS) {
    try { fs.writeFileSync(pathmod.join(d, name), data); } catch (e) { /* ignore */ }
  }
  frameCount++;
  process.stderr.write('[vm] saved frame ' + name + ' (' + data.length + ' bytes)\n');
  if (MAX_FRAMES > 0 && frameCount >= MAX_FRAMES) {
    exiting = true;
    throw new ExitException(0);
  }
}

function ExitException(code) { this.code = code; }
ExitException.prototype = Object.create(Error.prototype);

/* ------------------------------------------------------------- system call */

function doSyscall() {
  const num = R[2] | 0;
  const a0 = R[4] | 0, a1 = R[5] | 0, a2 = R[6] | 0, a3 = R[7] | 0;
  switch (num) {
    case 0: {                       /* read(fd, buf, count) */
      const fd = a0, addr = a1 >>> 0, len = a2 | 0;
      if (len < 0) return -EINVAL;
      if (addr + len > MEM_SIZE) fault(addr, 'read buffer');
      const buf = Buffer.from(membuf, addr, len);
      try {
        let n;
        const inf = files.get(fd);
        if (inf) {
          n = fs.readSync(fd, buf, 0, len, inf.pos);
          inf.pos += n;
        } else {
          n = fs.readSync(fd, buf, 0, len, null);
        }
        return n;
      } catch (e) {
        if (e.code === 'EAGAIN' || e.code === 'EOF') return 0;
        return -EIO;
      }
    }
    case 1: {                       /* write(fd, buf, count) */
      const fd = a0, addr = a1 >>> 0, len = a2 | 0;
      if (len < 0) return -EINVAL;
      if (addr + len > MEM_SIZE) fault(addr, 'write buffer');
      const buf = Buffer.from(membuf, addr, len);
      try {
        let n;
        const inf = files.get(fd);
        if (inf) {
          n = fs.writeSync(fd, buf, 0, len, inf.pos);
          inf.pos += n;
          inf.dirty = true;
        } else {
          n = fs.writeSync(fd, buf, 0, len);
        }
        return n;
      } catch (e) {
        return -EIO;
      }
    }
    case 2: {                       /* open(path, flags, mode) */
      const p = resolveGuestPath(cstr(a0 >>> 0));
      try {
        const fd = fs.openSync(p, flagsToNode(a1), a2 ? (a2 & 0o7777) : 0o644);
        const writable = (a1 & 3) !== O_RDONLY;
        files.set(fd, { pos: 0, path: p, writable, dirty: false });
        return fd;
      } catch (e) {
        return -(e.errno ? -e.errno : ENOENT);
      }
    }
    case 3: {                       /* close(fd) */
      const fd = a0;
      const inf = files.get(fd);
      try { if (fd > 2) fs.closeSync(fd); } catch (e) { return -EBADF; }
      files.delete(fd);
      if (inf && inf.writable && inf.dirty && isFramePath(inf.path)) archiveFrame(inf.path);
      return 0;
    }
    case 8: {                       /* lseek(fd, offset, whence) */
      const inf = files.get(a0);
      if (!inf) return -EBADF;
      let pos;
      if (a2 === 0) pos = a1 | 0;
      else if (a2 === 1) pos = inf.pos + (a1 | 0);
      else if (a2 === 2) {
