        try { size = fs.fstatSync(a0).size; } catch (e) { return -EBADF; }
        pos = size + (a1 | 0);
      } else return -EINVAL;
      if (pos < 0) return -EINVAL;
      inf.pos = pos;
      return pos | 0;
    }
