    }
    case 87: {                      /* unlink(path) */
      try { fs.unlinkSync(resolveGuestPath(cstr(a0 >>> 0))); }
      catch (e) { return -ENOENT; }
      return 0;
    }
    case 96: {                      /* gettimeofday(tv, tz) */
      if (a0) {
        const ms = Date.now();
        wr32(a0 >>> 0, Math.floor(ms / 1000) | 0);
        wr32((a0 + 4) >>> 0, ((ms % 1000) * 1000) | 0);
      }
      return 0;
    }
    case 201: {                     /* time(tloc) */
      const t = Math.floor(Date.now() / 1000) | 0;
      if (a0) wr32(a0 >>> 0, t);
      return t;
    }
    default:
      process.stderr.write('[vm] unimplemented syscall ' + num + ' (a0=' + a0 +
                           ') at pc=0x' + (pc >>> 0).toString(16) + '\n');
      return -ENOSYS;
  }
}

/* -------------------------------------------------------------- fpu helper */

function cop1(inst) {
  const rs = (inst >>> 21) & 31;        /* fmt / sub-opcode */
  const rt = (inst >>> 16) & 31;
  const fs_ = (inst >>> 11) & 31;
  const fd = (inst >>> 6) & 31;
  const funct = inst & 63;

  switch (rs) {
    case 0:  R[rt] = FGR[fs_] | 0; return;                     /* mfc1 */
    case 2:                                                    /* cfc1 */
      if (fs_ === 31) R[rt] = (FCSR | (FCC & 1) << 23 | ((FCC >>> 1) << 25)) | 0;
      else R[rt] = 0;
      return;
    case 3:  R[rt] = FGR[(fs_ & ~1) + 1] | 0; return;          /* mfhc1 */
    case 4:  FGR[fs_] = R[rt] >>> 0; return;                   /* mtc1 */
    case 6:                                                    /* ctc1 */
      if (fs_ === 31) { FCSR = R[rt] | 0; FCC = ((FCSR >>> 23) & 1) | (((FCSR >>> 25) & 0x7f) << 1); }
      return;
    case 7:  FGR[(fs_ & ~1) + 1] = R[rt] >>> 0; return;         /* mthc1 */
    case 8: {                                                  /* bc1f/bc1t */
      const cc = (inst >>> 18) & 7;
      const tf = (inst >>> 16) & 1;
      const cond = ((FCC >>> cc) & 1) === tf;
      if (cond) npc = (pc + 4 + (((inst << 16) >> 16) << 2)) >>> 0;
      return;
    }
    case 16: {                                                 /* single */
      const s = getS(fs_), t = getS(rt);
      switch (funct) {
        case 0: setS(fd, Math.fround(s + t)); return;
        case 1: setS(fd, Math.fround(s - t)); return;
        case 2: setS(fd, Math.fround(s * t)); return;
        case 3: setS(fd, Math.fround(s / t)); return;
        case 4: setS(fd, Math.fround(Math.sqrt(s))); return;
        case 5: setS(fd, Math.abs(s)); return;
        case 6: FGR[fd] = FGR[fs_]; return;                    /* mov.s */
        case 7: setS(fd, -s); return;
        case 12: FGR[fd] = roundW(s) >>> 0; return;            /* round.w.s */
        case 13: FGR[fd] = truncW(s) >>> 0; return;            /* trunc.w.s */
        case 14: FGR[fd] = (Math.ceil(s) | 0) >>> 0; return;
        case 15: FGR[fd] = (Math.floor(s) | 0) >>> 0; return;
        case 17: {                                             /* movcf.s */
          const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
          if (((FCC >>> cc) & 1) === tf) FGR[fd] = FGR[fs_];
          return;
        }
        case 18: if (R[rt] === 0) FGR[fd] = FGR[fs_]; return;  /* movz.s */
        case 19: if (R[rt] !== 0) FGR[fd] = FGR[fs_]; return;  /* movn.s */
        case 33: setD(fd, s); return;                          /* cvt.d.s */
        case 36: FGR[fd] = truncW(s) >>> 0; return;            /* cvt.w.s */
        default:
          if (funct >= 48) { fcompare(inst, s, t); return; }
          unimpl(inst, 'cop1.s');
      }
      return;
    }
    case 17: {                                                 /* double */
      const s = getD(fs_), t = getD(rt);
      switch (funct) {
        case 0: setD(fd, s + t); return;
        case 1: setD(fd, s - t); return;
        case 2: setD(fd, s * t); return;
        case 3: setD(fd, s / t); return;
        case 4: setD(fd, Math.sqrt(s)); return;
        case 5: setD(fd, Math.abs(s)); return;
        case 6: setD(fd, s); return;                           /* mov.d */
        case 7: setD(fd, -s); return;
        case 12: FGR[fd] = roundW(s) >>> 0; return;
        case 13: FGR[fd] = truncW(s) >>> 0; return;
        case 14: FGR[fd] = (Math.ceil(s) | 0) >>> 0; return;
        case 15: FGR[fd] = (Math.floor(s) | 0) >>> 0; return;
        case 17: {                                             /* movcf.d */
          const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
          if (((FCC >>> cc) & 1) === tf) setD(fd, s);
          return;
        }
        case 18: if (R[rt] === 0) setD(fd, s); return;
        case 19: if (R[rt] !== 0) setD(fd, s); return;
        case 32: setS(fd, Math.fround(s)); return;             /* cvt.s.d */
        case 36: FGR[fd] = truncW(s) >>> 0; return;            /* cvt.w.d */
        default:
          if (funct >= 48) { fcompare(inst, s, t); return; }
          unimpl(inst, 'cop1.d');
      }
      return;
    }
    case 20: {                                                 /* word fmt */
      const w = FGR[fs_] | 0;
      switch (funct) {
        case 32: setS(fd, Math.fround(w)); return;             /* cvt.s.w */
        case 33: setD(fd, w); return;                          /* cvt.d.w */
        default: unimpl(inst, 'cop1.w');
      }
      return;
    }
    default:
      unimpl(inst, 'cop1');
  }
}

function truncW(v) {
  if (!isFinite(v)) return 0x7fffffff;
  const t = Math.trunc(v);
  if (t > 2147483647 || t < -2147483648) return 0x7fffffff;
  return t | 0;
}
function roundW(v) {
  if (!isFinite(v)) return 0x7fffffff;
  let r = Math.round(v);
  if (Math.abs(v - Math.trunc(v)) === 0.5 && (r & 1)) r -= 1;   /* ties to even */
  if (r > 2147483647 || r < -2147483648) return 0x7fffffff;
  return r | 0;
}

function fcompare(inst, s, t) {
  const cond = inst & 15;
  const cc = (inst >>> 8) & 7;
  const un = (s !== s) || (t !== t);
  let res;
  if (un) res = (cond & 1) !== 0;
  else {
    const lt = s < t, eq = s === t;
    res = ((cond & 4) && lt) || ((cond & 2) && eq) ? true : false;
  }
  if (res) FCC |= (1 << cc); else FCC &= ~(1 << cc);
}

function unimpl(inst, where) {
  throw new Error('unimplemented instruction 0x' + (inst >>> 0).toString(16) +
                  ' (' + where + ') at pc=0x' + (pc >>> 0).toString(16));
}

/* ------------------------------------------------------------- interpreter */

function run() {
  for (;;) {
    const cpc = pc >>> 0;
    if (cpc + 4 > MEM_SIZE) fault(cpc, 'fetch');
    const inst = I32[cpc >>> 2];
    const next = npc >>> 0;
    npc = (next + 4) >>> 0;

    const op = inst >>> 26;
    const rs = (inst >>> 21) & 31;
    const rt = (inst >>> 16) & 31;

    switch (op) {
      case 0: {                                    /* SPECIAL */
        const rd = (inst >>> 11) & 31;
        const sa = (inst >>> 6) & 31;
        switch (inst & 63) {
          case 0: R[rd] = R[rt] << sa; break;                       /* sll */
          case 1: {                                                 /* movci */
            const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
            if (((FCC >>> cc) & 1) === tf) R[rd] = R[rs];
            break;
          }
          case 2:
            if ((inst >>> 21) & 1) {                                /* rotr */
              const v = R[rt] >>> 0;
              R[rd] = sa === 0 ? v | 0 : ((v >>> sa) | (v << (32 - sa))) | 0;
            } else R[rd] = R[rt] >>> sa;                            /* srl */
            break;
          case 3: R[rd] = R[rt] >> sa; break;                       /* sra */
          case 4: R[rd] = R[rt] << (R[rs] & 31); break;             /* sllv */
          case 6:
            if ((inst >>> 6) & 1) {                                 /* rotrv */
              const v = R[rt] >>> 0, s = R[rs] & 31;
              R[rd] = s === 0 ? v | 0 : ((v >>> s) | (v << (32 - s))) | 0;
            } else R[rd] = R[rt] >>> (R[rs] & 31);                  /* srlv */
            break;
          case 7: R[rd] = R[rt] >> (R[rs] & 31); break;             /* srav */
          case 8: npc = R[rs] >>> 0; break;                         /* jr */
          case 9: R[rd === 0 ? 31 : rd] = (cpc + 8) | 0; npc = R[rs] >>> 0; break; /* jalr */
          case 10: if (R[rt] === 0) R[rd] = R[rs]; break;           /* movz */
          case 11: if (R[rt] !== 0) R[rd] = R[rs]; break;           /* movn */
          case 12: {                                                /* syscall */
            pc = next; R[2] = doSyscall() | 0; continue;
          }
          case 13:                                                  /* break */
            throw new Error('break instruction at 0x' + cpc.toString(16));
          case 15: break;                                           /* sync */
          case 16: R[rd] = HI; break;
          case 17: HI = R[rs]; break;
          case 18: R[rd] = LO; break;
          case 19: LO = R[rs]; break;
          case 24: {                                                /* mult */
            const a = R[rs] | 0, b = R[rt] | 0;
            LO = Math.imul(a, b) | 0;
            let hi = umulHi(a >>> 0, b >>> 0);
            if (a < 0) hi = (hi - (b >>> 0)) | 0;
            if (b < 0) hi = (hi - (a >>> 0)) | 0;
            HI = hi | 0;
            break;
          }
          case 25: {                                                /* multu */
            const a = R[rs] >>> 0, b = R[rt] >>> 0;
            LO = Math.imul(a | 0, b | 0) | 0;
            HI = umulHi(a, b) | 0;
            break;
          }
          case 26: {                                                /* div */
            const a = R[rs] | 0, b = R[rt] | 0;
            if (b === 0) { LO = 0; HI = a; }
            else if (a === -2147483648 && b === -1) { LO = -2147483648; HI = 0; }
            else { LO = (a / b) | 0; HI = (a % b) | 0; }
            break;
          }
          case 27: {                                                /* divu */
            const a = R[rs] >>> 0, b = R[rt] >>> 0;
            if (b === 0) { LO = 0; HI = a | 0; }
            else { LO = (a / b) >>> 0 | 0; HI = (a % b) | 0; }
            break;
          }
          case 32: case 33: R[rd] = (R[rs] + R[rt]) | 0; break;      /* add/addu */
          case 34: case 35: R[rd] = (R[rs] - R[rt]) | 0; break;      /* sub/subu */
          case 36: R[rd] = R[rs] & R[rt]; break;
          case 37: R[rd] = R[rs] | R[rt]; break;
          case 38: R[rd] = R[rs] ^ R[rt]; break;
          case 39: R[rd] = ~(R[rs] | R[rt]); break;
          case 42: R[rd] = R[rs] < R[rt] ? 1 : 0; break;             /* slt */
          case 43: R[rd] = (R[rs] >>> 0) < (R[rt] >>> 0) ? 1 : 0; break;
          case 48: if (R[rs] >= R[rt]) trap(cpc, 'tge'); break;
          case 49: if ((R[rs] >>> 0) >= (R[rt] >>> 0)) trap(cpc, 'tgeu'); break;
          case 50: if (R[rs] < R[rt]) trap(cpc, 'tlt'); break;
          case 51: if ((R[rs] >>> 0) < (R[rt] >>> 0)) trap(cpc, 'tltu'); break;
          case 52: if (R[rs] === R[rt]) trap(cpc, 'teq'); break;
          case 54: if (R[rs] !== R[rt]) trap(cpc, 'tne'); break;
          default: unimpl(inst, 'special');
        }
        break;
      }
      case 1: {                                    /* REGIMM */
        const off = (((inst << 16) >> 16) << 2);
        switch (rt) {
          case 0: if (R[rs] < 0) npc = (cpc + 4 + off) >>> 0; break;   /* bltz */
          case 1: if (R[rs] >= 0) npc = (cpc + 4 + off) >>> 0; break;  /* bgez */
          case 16: R[31] = (cpc + 8) | 0; if (R[rs] < 0) npc = (cpc + 4 + off) >>> 0; break;
          case 17: R[31] = (cpc + 8) | 0; if (R[rs] >= 0) npc = (cpc + 4 + off) >>> 0; break;
          default: unimpl(inst, 'regimm');
        }
        break;
      }
      case 2: npc = (((cpc + 4) & 0xf0000000) | ((inst & 0x3ffffff) << 2)) >>> 0; break;   /* j */
      case 3:                                                                             /* jal */
        R[31] = (cpc + 8) | 0;
        npc = (((cpc + 4) & 0xf0000000) | ((inst & 0x3ffffff) << 2)) >>> 0;
        break;
      case 4: if (R[rs] === R[rt]) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) >>> 0; break;
      case 5: if (R[rs] !== R[rt]) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) >>> 0; break;
      case 6: if (R[rs] <= 0) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) >>> 0; break;
      case 7: if (R[rs] > 0) npc = (cpc + 4 + (((inst << 16) >> 16) << 2)) >>> 0; break;
      case 8: case 9: R[rt] = (R[rs] + ((inst << 16) >> 16)) | 0; break;       /* addi/addiu */
      case 10: R[rt] = R[rs] < ((inst << 16) >> 16) ? 1 : 0; break;            /* slti */
      case 11: R[rt] = (R[rs] >>> 0) < ((((inst << 16) >> 16)) >>> 0) ? 1 : 0; break; /* sltiu */
      case 12: R[rt] = R[rs] & (inst & 0xffff); break;
      case 13: R[rt] = R[rs] | (inst & 0xffff); break;
      case 14: R[rt] = R[rs] ^ (inst & 0xffff); break;
      case 15: R[rt] = (inst & 0xffff) << 16; break;                           /* lui */
      case 17: cop1(inst); break;
      case 28: {                                   /* SPECIAL2 */
        const rd = (inst >>> 11) & 31;
        switch (inst & 63) {
          case 0: {                                                 /* madd */
            const a = R[rs] | 0, b = R[rt] | 0;
            let lo = Math.imul(a, b) >>> 0;
            let hi = umulHi(a >>> 0, b >>> 0);
            if (a < 0) hi = (hi - (b >>> 0)) >>> 0;
            if (b < 0) hi = (hi - (a >>> 0)) >>> 0;
            const nlo = (LO >>> 0) + lo;
            LO = nlo | 0;
            HI = ((HI >>> 0) + hi + (nlo > 0xffffffff ? 1 : 0)) | 0;
            break;
          }
          case 1: {                                                 /* maddu */
            const a = R[rs] >>> 0, b = R[rt] >>> 0;
            const lo = Math.imul(a | 0, b | 0) >>> 0;
            const hi = umulHi(a, b);
            const nlo = (LO >>> 0) + lo;
            LO = nlo | 0;
            HI = ((HI >>> 0) + hi + (nlo > 0xffffffff ? 1 : 0)) | 0;
            break;
          }
          case 2: R[rd] = Math.imul(R[rs], R[rt]) | 0; break;        /* mul */
          case 32: {                                                /* clz */
            const v = R[rs] >>> 0;
            R[rd] = v === 0 ? 32 : Math.clz32(v);
            break;
          }
          case 33: {                                                /* clo */
            const v = ~R[rs] >>> 0;
            R[rd] = v === 0 ? 32 : Math.clz32(v);
            break;
          }
          default: unimpl(inst, 'special2');
        }
        break;
      }
      case 31: {                                   /* SPECIAL3 */
        const rd = (inst >>> 11) & 31;
        const sa = (inst >>> 6) & 31;
        switch (inst & 63) {
          case 0: {                                                 /* ext */
            const size = rd + 1, posn = sa;
            R[rt] = size === 32 ? (R[rs] >>> posn)
                                : ((R[rs] >>> posn) & ((1 << size) - 1));
            break;
          }
          case 4: {                                                 /* ins */
            const posn = sa, msb = rd;
            const size = msb - posn + 1;
            const mask = size === 32 ? 0xffffffff : (((1 << size) - 1) << posn);
            R[rt] = ((R[rt] & ~mask) | ((R[rs] << posn) & mask)) | 0;
            break;
          }
          case 32: {                                                /* BSHFL */
            switch (sa) {
              case 2: {                                             /* wsbh */
                const v = R[rt] >>> 0;
                R[rd] = (((v & 0x00ff00ff) << 8) | ((v >>> 8) & 0x00ff00ff)) | 0;
                break;
              }
              case 16: R[rd] = (R[rt] << 24) >> 24; break;           /* seb */
              case 24: R[rd] = (R[rt] << 16) >> 16; break;           /* seh */
              default: unimpl(inst, 'bshfl');
            }
            break;
          }
          case 59: R[rt] = 0; break;                                /* rdhwr */
          default: unimpl(inst, 'special3');
        }
        break;
      }
      /* ------------------------------------------------------------ loads */
      case 32: {                                                    /* lb */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a >= MEM_SIZE) fault(a, 'lb');
        R[rt] = I8[a];
        break;
      }
      case 33: {                                                    /* lh */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a + 2 > MEM_SIZE) fault(a, 'lh');
        R[rt] = (a & 1) ? ((U8[a] | (U8[a + 1] << 8)) << 16) >> 16 : I16[a >>> 1];
        break;
      }
      case 34: {                                                    /* lwl */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        const k = a & 3;
        const w = rd32((a & ~3) >>> 0);
        const sh = 24 - 8 * k;
        R[rt] = sh === 0 ? w : ((w << sh) | (R[rt] & ((1 << sh) - 1))) | 0;
        break;
      }
      case 35: {                                                    /* lw */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a + 4 > MEM_SIZE) fault(a, 'lw');
        R[rt] = (a & 3) ? rd32(a) : I32[a >>> 2];
        break;
      }
      case 36: {                                                    /* lbu */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a >= MEM_SIZE) fault(a, 'lbu');
        R[rt] = U8[a];
        break;
      }
      case 37: {                                                    /* lhu */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a + 2 > MEM_SIZE) fault(a, 'lhu');
        R[rt] = (a & 1) ? (U8[a] | (U8[a + 1] << 8)) : U16[a >>> 1];
        break;
      }
      case 38: {                                                    /* lwr */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        const k = a & 3;
        const w = rd32((a & ~3) >>> 0);
        R[rt] = k === 0 ? w : (((w >>> (8 * k)) | (R[rt] & ~(0xffffffff >>> (8 * k)))) | 0);
        break;
      }
      /* ----------------------------------------------------------- stores */
      case 40: {                                                    /* sb */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a >= MEM_SIZE) fault(a, 'sb');
        U8[a] = R[rt];
        break;
      }
      case 41: {                                                    /* sh */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a + 2 > MEM_SIZE) fault(a, 'sh');
        if (a & 1) { U8[a] = R[rt]; U8[a + 1] = R[rt] >>> 8; }
        else U16[a >>> 1] = R[rt];
        break;
      }
      case 42: {                                                    /* swl */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        const k = a & 3, base = (a & ~3) >>> 0;
        const w = rd32(base);
        const sh = 24 - 8 * k;
        const mask = 0xffffffff >>> sh;
        wr32(base, ((w & ~mask) | ((R[rt] >>> sh) & mask)) | 0);
        break;
      }
      case 43: {                                                    /* sw */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        if (a + 4 > MEM_SIZE) fault(a, 'sw');
        if (a & 3) wr32(a, R[rt]); else I32[a >>> 2] = R[rt];
        break;
      }
      case 46: {                                                    /* swr */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        const k = a & 3, base = (a & ~3) >>> 0;
        const w = rd32(base);
        const mask = (0xffffffff << (8 * k)) | 0;
        wr32(base, ((w & ~mask) | ((R[rt] << (8 * k)) & mask)) | 0);
        break;
      }
      case 47: break;                                               /* cache */
      case 51: break;                                               /* pref */
      case 48: {                                                    /* ll */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        R[rt] = rd32(a);
        break;
      }
      case 56: {                                                    /* sc */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        wr32(a, R[rt]);
        R[rt] = 1;
        break;
      }
      case 49: {                                                    /* lwc1 */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        FGR[rt] = rd32(a) >>> 0;
        break;
      }
      case 57: {                                                    /* swc1 */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        wr32(a, FGR[rt] | 0);
        break;
      }
      case 53: {                                                    /* ldc1 */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        FGR[rt & ~1] = rd32(a) >>> 0;
        FGR[(rt & ~1) + 1] = rd32((a + 4) >>> 0) >>> 0;
        break;
      }
      case 61: {                                                    /* sdc1 */
        const a = (R[rs] + ((inst << 16) >> 16)) >>> 0;
        wr32(a, FGR[rt & ~1] | 0);
        wr32((a + 4) >>> 0, FGR[(rt & ~1) + 1] | 0);
        break;
      }
      default:
        unimpl(inst, 'opcode ' + op);
    }

    R[0] = 0;
    pc = next;
  }
}

function trap(addr, kind) {
  throw new Error('trap (' + kind + ') at 0x' + (addr >>> 0).toString(16));
}

/* ------------------------------------------------------------------- main */

process.stderr.write('[vm] loading ' + ELF_PATH + ', entry 0x' +
                     elf.entry.toString(16) + ', memory ' +
                     (MEM_SIZE / (1024 * 1024)).toFixed(0) + ' MiB\n');

const t0 = Date.now();
let exitCode = 0;
try {
  run();
} catch (e) {
  if (e instanceof ExitException) {
    exitCode = e.code | 0;
    process.stderr.write('[vm] guest exited with status ' + exitCode + '\n');
  } else {
    process.stderr.write('[vm] ' + (e && e.stack ? e.stack : e) + '\n');
    exitCode = 1;
  }
}
process.stderr.write('[vm] frames saved: ' + frameCount +
                     ', elapsed ' + ((Date.now() - t0) / 1000).toFixed(1) + 's\n');
process.exit(exitCode);
